    void Restore(){Show();WindowState=FormWindowState.Normal;Activate();}
    void Save(){try{s.Save();}catch(Exception e){MessageBox.Show(this,"Could not save settings: "+e.Message,"NightLens");}}
    async Task Locate(){s.RestoreSaved();if(!s.WindowsLocation){locationStatus="Saved observing location";return;}GeoCoordinate result=null;try{var locator=new Windows.Devices.Geolocation.Geolocator{DesiredAccuracy=Windows.Devices.Geolocation.PositionAccuracy.Default};var completion=new TaskCompletionSource<Windows.Devices.Geolocation.Geoposition>();var operation=locator.GetGeopositionAsync(TimeSpan.FromMinutes(15),TimeSpan.FromSeconds(12));operation.Completed=(op,state)=>{try{completion.TrySetResult(op.GetResults());}catch(Exception e){completion.TrySetException(e);}};if(await Task.WhenAny(completion.Task,Task.Delay(14000))==completion.Task){var position=await completion.Task;if((DateTimeOffset.UtcNow-position.Coordinate.Timestamp).TotalMinutes<30)result=new GeoCoordinate(position.Coordinate.Point.Position.Latitude,position.Coordinate.Point.Position.Longitude);}else operation.Cancel();}catch{}
        if(result!=null){s.Lat=result.Latitude;s.Lon=result.Longitude;s.Zone=TimeZoneInfo.Local.Id;s.Place="Windows location";locationStatus="Windows Location";}else locationStatus="Windows Location unavailable · using saved location";
    }
    public async Task RefreshData(bool locate){if(busy)return;busy=true;PaintView();try{if(locate){StartupProgress?.Invoke("Finding your observing location…");await Locate();}StartupProgress?.Invoke("Fetching forecast…");f=await Task.Run(()=>Forecast.Fetch(s));if(s.WindowsLocation&&s.Place=="Windows location"){var zone=LocationForm.MapZone(f.IanaZone);if(zone!=null)s.Zone=zone;}clock=DateTime.UtcNow;fetched=clock;StartupProgress?.Invoke("Scoring targets for tonight…");n=await Task.Run(()=>new Night(s,f,clock,planningDate));page=0;Save();}catch(Exception e){if(StartupProgress==null)MessageBox.Show(this,"Could not update tonight: "+e.Message,"NightLens");else StartupProgress("Planning offline — open Settings or try Refresh");}finally{busy=false;PaintView();}}
    async Task Recalculate(){if(busy||f==null)return;busy=true;PaintView();try{clock=DateTime.UtcNow;n=await Task.Run(()=>new Night(s,f,clock,planningDate));page=0;}finally{busy=false;PaintView();}}
    public async Task ChangeLens(string lens){var active=s.Rigs[s.Active];var candidate=Json.Read<Rig>(Json.Write(active));EquipmentLibrary.SelectLens(candidate,lens);if(candidate.SensorW<=0||candidate.SensorH<=0){using(var dialog=new OpticalSpecsForm(candidate)){dialog.Text="Lens specifications needed";if(dialog.ShowDialog(this)!=DialogResult.OK){PaintView();return;}}}if(lens=="Wide"){candidate.SmartWideSensorW=candidate.SensorW;candidate.SmartWideSensorH=candidate.SensorH;}s.Rigs[s.Active]=candidate;if(!test)Save();await Recalculate();}
