pin.Checked;TopMost=s.Pinned;Save();};menu.Items.Add(pin);menu.Items.Add(updates?.Available==null?"Updates…":"Update to "+updates.Available.Version+"…",null,(a,b)=>{if(updates!=null)using(var dialog=new UpdateForm(this,updates))dialog.ShowDialog(this);});menu.Items.Add("About & data sources…",null,(a,b)=>ShowAbout());menu.Show((Control)sender,new Point(0,((Control)sender).Height));await Task.CompletedTask;}
