    public void PaintView(){SuspendLayout();var old=root;bool shortView=ClientSize.Height<650;int perPage=1,hourCount=shortView?4:6;root=Style.Grid(1,59,37,145,-100,25);root.Padding=new Padding(10);root.AutoScroll=false;Controls.Add(root);BackColor=Style.Bg;ForeColor=Style.Text;if(old!=null){Controls.Remove(old);old.Dispose();}
        var header=Style.Grid(2,-100);header.ColumnStyles[0].Width=100;header.ColumnStyles[1].SizeType=SizeType.Absolute;header.ColumnStyles[1].Width=40;var title=Style.Grid(1,34,-100);title.Controls.Add(Style.Label("NightLens · Your sky tonight",18,true),0,0);var siteRow=Style.Grid(3,-100);siteRow.ColumnStyles[0].SizeType=SizeType.Percent;siteRow.ColumnStyles[0].Width=100;siteRow.ColumnStyles[1].SizeType=SizeType.Absolute;siteRow.ColumnStyles[1].Width=35;siteRow.ColumnStyles[2].SizeType=SizeType.Absolute;siteRow.ColumnStyles[2].Width=220;siteRow.Controls.Add(Style.Label(s.Place+"  ·  "+(n!=null?s.Local(n.Start).ToString("ddd, MMM d")+" → "+s.Local(n.End).ToString("ddd, MMM d"):"Tonight"),11),0,0);siteRow.Controls.Add(Style.Label("Site",9,true),1,0);var sitePicker=Style.Combo();sitePicker.Dock=DockStyle.Fill;sitePicker.AccessibleName="Observing site";sitePicker.Margin=Padding.Empty;sitePicker.Items.Add(new SiteChoice{Label="Windows location",Id="__windows"});sitePicker.Items.Add(new SiteChoice{Label="Saved fallback",Id="__fallback"});foreach(var entry in s.Sites)sitePicker.Items.Add(new SiteChoice{Label=entry.Name,Id=entry.Id});sitePicker.Items.Add(new SiteChoice{Label="Manage sites…",Id="__manage"});string activeSite=s.WindowsLocation?"__windows":s.ActiveSiteId??"__fallback";sitePicker.SelectedItem=sitePicker.Items.Cast<SiteChoice>().FirstOrDefault(x=>x.Id==activeSite)??sitePicker.Items[1];sitePicker.Enabled=!busy;sitePicker.SelectionChangeCommitted+=async(a,b)=>await ChooseSite(((SiteChoice)sitePicker.SelectedItem).Id);siteRow.Controls.Add(sitePicker,2,0);title.Controls.Add(siteRow,0,1);header.Controls.Add(title,0,0);var gear=Style.Button("",Gear);gear.Tag="gear";gear.AccessibleName="Settings";gear.Font=new Font("Segoe UI Symbol",24);gear.Dock=DockStyle.Fill;gear.Enabled=!busy;header.Controls.Add(gear,1,0);root.Controls.Add(header,0,0);
