        if(n.Picks.Count>0){var pick=n.Picks[page];cards.Controls.Add(ObjectView.Create(pick,n,active,this,!test),0,0);}else cards.Controls.Add(Style.CardBox("No suitable targets for this night","No selected-catalog objects meet the full-night darkness and altitude rules. Choose a different night or catalog."),0,0);
