class LocationForm:Form {
    public Settings Result;TextBox name,lat,lon,search;ComboBox zones,places;CheckBox auto,fahrenheit;Label message;List<Dictionary<string,object>> matches=new List<Dictionary<string,object>>();
    public LocationForm(Settings input){Result=input.SavedCopy();input=Result;Style.Form(this);Text="Location settings";Style.FitScreen(this,820,480);var root=Style.Grid(1,37,-100,39);root.Padding=new Padding(12);Controls.Add(root);root.Controls.Add(Style.Label("Observing location",20,true),0,0);var fields=Style.Grid(2,32,24,53,53,53,53,28);var options=Style.Grid(2,-100);auto=new CheckBox{Text="Use Windows Location when available",Checked=input.WindowsLocation,Dock=DockStyle.Fill};options.Controls.Add(auto,0,0);options.Controls.Add(Style.Button("Windows Location settings",(a,b)=>System.Diagnostics.Process.Start("ms-settings:privacy-location")),1,0);fields.Controls.Add(options,0,0);fields.SetColumnSpan(options,2);var note=Style.Label("If Windows Location is unavailable, use the saved location below.",9);fields.Controls.Add(note,0,1);fields.SetColumnSpan(note,2);
        var city=Style.Grid(2,-100);city.ColumnStyles[0].Width=74;city.ColumnStyles[1].Width=26;search=new TextBox{Dock=DockStyle.Fill,Text="Centennial",Margin=new Padding(0,3,5,0)};city.Controls.Add(search,0,0);city.Controls.Add(Style.Button("Find city",async(a,b)=>await Find()),1,0);fields.Controls.Add(Style.Field("Search for a city",city),0,2);places=Style.Combo();places.SelectedIndexChanged+=(a,b)=>SelectPlace();fields.Controls.Add(Style.Field("Choose a search result",places),1,2);
        name=new TextBox{Text=input.Place};var place=Style.Field("Saved place name",name);fields.Controls.Add(place,0,3);fields.SetColumnSpan(place,2);lat=new TextBox{Text=Net.Coord(input.Lat)};lon=new TextBox{Text=Net.Coord(input.Lon)};fields.Controls.Add(Style.Field("Latitude (−90 to 90)",lat),0,4);fields.Controls.Add(Style.Field("Longitude (−180 to 180; west is negative)",lon),1,4);
        zones=Style.Combo();foreach(var z in TimeZoneInfo.GetSystemTimeZones())zones.Items.Add(z);zones.DisplayMember="DisplayName";Style.DarkCombo(zones);zones.SelectedItem=zones.Items.Cast<TimeZoneInfo>().FirstOrDefault(z=>z.Id==input.Zone);var zoneField=Style.Field("Time zone for saved location",zones);fields.Controls.Add(zoneField,0,5);fields.SetColumnSpan(zoneField,2);fahrenheit=new CheckBox{Text="Use Fahrenheit and mph",Checked=input.Fahrenheit,Dock=DockStyle.Fill};fields.Controls.Add(fahrenheit,0,6);root.Controls.Add(fields,0,1);var footer=Style.Grid(2,-100);footer.ColumnStyles[0].Width=75;footer.ColumnStyles[1].Width=25;message=Style.Label("",9);footer.Controls.Add(message,0,0);var save=Style.Button("Save location",(a,b)=>Apply());save.AccessibleName="Save location";footer.Controls.Add(save,1,0);root.Controls.Add(footer,0,2);AcceptButton=save;
    }
    async Task Find(){message.Text="Searching…";try{string data=await Task.Run(()=>Net.Get("https://geocoding-api.open-meteo.com/v1/search?name="+Uri.EscapeDataString(search.Text.Trim())+"&count=10&language=en&format=json"));var d=Json.Obj(data);places.Items.Clear();matches.Clear();if(d.ContainsKey("results"))foreach(var x in Json.Arr(d["results"])){var r=(Dictionary<string,object>)x;matches.Add(r);places.Items.Add(r["name"]+", "+(r.ContainsKey("admin1")?r["admin1"]+", ":"")+(r.ContainsKey("country")?r["country"]:""));}message.Text=matches.Count>0?"Choose the matching place, then save.":"No places found; enter coordinates instead.";if(matches.Count>0)places.SelectedIndex=0;}catch{message.Text="City search unavailable; enter coordinates and time zone.";}}
    void SelectPlace(){if(places.SelectedIndex<0)return;var r=matches[places.SelectedIndex];name.Text=places.Text;lat.Text=Net.Coord(Json.Num(r["latitude"]));lon.Text=Net.Coord(Json.Num(r["longitude"]));string id=MapZone(Convert.ToString(r["timezone"]));zones.SelectedItem=zones.Items.Cast<TimeZoneInfo>().FirstOrDefault(z=>z.Id==id);if(zones.SelectedIndex<0)message.Text="Choose the time zone manually.";}
    public static string MapZone(string iana){try{using(var stream=typeof(LocationForm).Assembly.GetManifestResourceStream("windowsZones.xml")){var xml=XDocument.Load(stream);var node=xml.Descendants("mapZone").FirstOrDefault(x=>((string)x.Attribute("type")).Split(' ').Contains(iana));return node==null?null:(string)node.Attribute("other");}}catch{return null;}}
    void Apply(){double la,lo;if(!double.TryParse(lat.Text,NumberStyles.Float,CultureInfo.InvariantCulture,out la)||double.IsNaN(la)||Math.Abs(la)>90||!double.TryParse(lon.Text,NumberStyles.Float,CultureInfo.InvariantCulture,out lo)||double.IsNaN(lo)||Math.Abs(lo)>180||zones.SelectedItem==null||string.IsNullOrWhiteSpace(name.Text)){message.Text="Enter a name, valid coordinates and a time zone.";return;}if(Math.Abs(Result.SavedLat-la)>.00001||Math.Abs(Result.SavedLon-lo)>.00001||Result.SavedPlace!=name.Text.Trim()||Result.SavedZone!=((TimeZoneInfo)zones.SelectedItem).Id)Result.ActiveSiteId=null;Result.Place=Result.SavedPlace=name.Text.Trim();Result.Lat=Result.SavedLat=la;Result.Lon=Result.SavedLon=lo;Result.Zone=Result.SavedZone=((TimeZoneInfo)zones.SelectedItem).Id;Result.WindowsLocation=auto.Checked;Result.Fahrenheit=fahrenheit.Checked;DialogResult=DialogResult.OK;Close();}
}

class CatalogForm:Form {
    public List<string> SelectedCatalogs;public bool IncludeSolar;CheckedListBox list;CheckBox solar;Label message;
    public CatalogForm(Settings settings){SelectedCatalogs=new List<string>(settings.EnabledCatalogs??new List<string>());IncludeSolar=settings.IncludeSolar;Style.Form(this);Text="Catalog settings";Style.FitScreen(this,840,490);var root=Style.Grid(1,37,50,-100,38,32,40);root.Padding=new Padding(12);Controls.Add(root);root.Controls.Add(Style.Label("Deep-sky catalogs",20,true),0,0);root.Controls.Add(Style.Label("Check the catalog files you want to use. Objects shared by catalogs appear once.\nOpenNGC files are separate, local and available offline; import other catalogs below.",10),0,1);list=new CheckedListBox{Dock=DockStyle.Fill,CheckOnClick=true,BackColor=Style.Card,ForeColor=Style.Text,BorderStyle=BorderStyle.FixedSingle,IntegralHeight=false};root.Controls.Add(list,0,2);Reload();var actions=Style.Grid(3,-100);actions.Controls.Add(Style.Button("Import catalog CSV…",(a,b)=>Import()),0,0);actions.Controls.Add(Style.Button("Open catalog folder",(a,b)=>System.Diagnostics.Process.Start("explorer.exe",CatalogLibrary.BuiltIn)),1,0);solar=new CheckBox{Text="Include Moon and planets",Checked=IncludeSolar,Dock=DockStyle.Fill};actions.Controls.Add(solar,2,0);root.Controls.Add(actions,0,3);message=Style.Label("Counts exclude nonexistent/duplicate records and records without valid coordinates.",9);root.Controls.Add(message,0,4);var save=Style.Button("Save catalog selection",(a,b)=>{SelectedCatalogs=list.CheckedItems.Cast<CatalogInfo>().Select(x=>x.Key).ToList();IncludeSolar=solar.Checked;DialogResult=DialogResult.OK;Close();});root.Controls.Add(save,0,5);AcceptButton=save;}
    void Reload(){list.Items.Clear();foreach(var item in CatalogLibrary.Available())list.Items.Add(item,SelectedCatalogs.Contains(item.Key));}
    void Import(){using(var picker=new OpenFileDialog{Filter="Catalog CSV (*.csv)|*.csv",Title="Choose an OpenNGC or NightLens-format catalog"}){if(picker.ShowDialog(this)!=DialogResult.OK)return;try{var catalog=CatalogLibrary.Read(picker.FileName);if(catalog.Error!="")throw new Exception(catalog.Error);if(catalog.Skipped>0&&MessageBox.Show(this,catalog.Skipped+" records cannot be planned. Import the remaining "+catalog.Targets.Count+" targets?","Catalog validation",MessageBoxButtons.OKCancel)!=DialogResult.OK)return;Directory.CreateDirectory(CatalogLibrary.Imported);string key=Path.GetFileName(picker.FileName);string destination=Path.Combine(CatalogLibrary.Imported,key);if(CatalogLibrary.Available().Any(x=>x.Key.Equals(key,StringComparison.OrdinalIgnoreCase)))throw new Exception("A catalog with this filename already exists. Rename your file to keep both catalogs.");File.Copy(picker.FileName,destination,false);SelectedCatalogs=list.CheckedItems.Cast<CatalogInfo>().Select(x=>x.Key).ToList();SelectedCatalogs.Add(key);Reload();message.Text="Imported "+catalog.Targets.Count.ToString("N0")+" targets. Save to use this selection.";}catch(Exception e){MessageBox.Show(this,"Catalog not imported: "+e.Message+"\n\nUse OpenNGC format or columns: Name, Type, RAHours, DecDegrees, MajorArcmin, MinorArcmin, optional Magnitude and CanonicalId.","NightLens");}}}
}
